import{z as s,x as l,o as e,c as C,q as n,j as B,D as E,d as t,s as i,S as o,b as A}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"短长期与沉没成本","description":"","frontmatter":{"title":"短长期与沉没成本","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/sunk-cost.md","filePath":"econ/sunk-cost.md","lastUpdated":1791063341000}'),p={name:"econ/sunk-cost.md"};function m(d,a,F,h,_,c){const r=l("Mermaid");return e(),C("div",null,[a[2]||(a[2]=n('<h1 id="短长期与沉没成本" tabindex="-1">短长期与沉没成本 <a class="header-anchor" href="#短长期与沉没成本" aria-label="Permalink to &quot;短长期与沉没成本&quot;">​</a></h1><div class="epigraph"><p>长期平均成本是一族短期平均成本的下包络；短期里已经钉死的工厂规模，不能再当成决策变量。</p><footer>—— 据 Viner, Cost Curves and Supply Curves, Zeitschrift für Nationalökonomie, 1931 整理</footer></div><p><a href="/econ/profit-supply">上一课</a>（利润最大化与供给）。在一切投入可按 \\(w\\) 重选时写出 \\(p=\\mathrm{MC}\\) 与 Hotelling。本课不重讲利润函数的凸性。缺口是：真实决策有时间分层——厂房、执照、已经付出的研发，并不能在本期按租金退回。若仍用全部 \\(c(w,q)\\) 当相关成本，歇业规则和供给弹性都会写错。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>把投入分成在本期可调的 \\(z_v\\) 与已经固定的 \\(z_f\\)。短期成本是</p> \\[c_{\\mathrm{SR}}(w,q;z_f)=w_v\\cdot z_v(q;z_f)+w_f\\cdot z_f, \\]<p>其中第二项若<strong>沉没</strong>，则决策时它不可避：比较的是收入与可变成本，不是与全部会计成本。缺口因此不是再发明一条 MC，而是问：哪些数字进入本期的机会成本？沉没的定义是事后无法收回，与「固定但可避」（尚未付出、选择歇业就不付）不是同一件事。</p><p>长期：所有 \\(z\\) 可调，\\(c_{\\mathrm{LR}}(w,q)=\\min_{z_f}c_{\\mathrm{SR}}(w,q;z_f)\\)。包络定理给出：长期 MC 曲线穿过每条短期 MC 在最优规模处的点；长期 AC 是短期 AC 的下包络。Viner 的图解把这层几何钉死；后课完全竞争的短、长期供给正是读这两条 MC。</p><h3 id="沉没不是固定-固定不必沉没" tabindex="-1">沉没不是固定，固定不必沉没 <a class="header-anchor" href="#沉没不是固定-固定不必沉没" aria-label="Permalink to &quot;沉没不是固定，固定不必沉没&quot;">​</a></h3><p>教科书常把「固定成本」画成 AC 与 AVC 的垂直距离。若这笔钱尚未付出、歇业可免，它影响进入，不影响已经在场的短期停产。若已经付出且不能转卖，它两头都不影响：既不改短期停产（只比 \\(p\\) 与 AVC），也不该进入事后的利润核算当「还要再付一次」。把沉没写进短期 MC，会让供给左移——那是会计，不是决策。</p><p><span class="marginnote">停产规则：短期若 \\(p\\lt \\min\\mathrm{AVC}\\)，产量为零；若 \\(\\min\\mathrm{AVC}\\le p\\lt \\min\\mathrm{AC}\\) 且固定部分已沉没，仍生产、会计亏损。长期不存在「沉没」：不弥补 \\(c_{\\mathrm{LR}}\\) 就退出。</span></p><p><span class="marginnote">数字实例：租的厂房月租 5 万（还没付、退租可免）是可避固定；已花 300 万购入的专用模具、转卖只值 10 万，则 290 万是沉没。今晚要不要开工，只看订单收入能否盖住电费和人工——房租还没付要不要退、模具当初花了多少，都不进这道题。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>给定 \\(z_f\\)，短期供给仍是 \\(p=\\mathrm{MC}_{\\mathrm{SR}}(q;z_f)\\)，定义域在停产点以上。\\(z_f\\) 不同，得到一族短期供给。长期供给沿 \\(\\mathrm{MC}_{\\mathrm{LR}}\\)，并且 \\(z_f\\) 被选在使 \\(c_{\\mathrm{SR}}\\) 最小的规模上。CRS 加沉没的进入成本时，长期平均成本可以先降后平，后课自由进入会把价格钉在 \\(\\min\\mathrm{AC}\\)。</p><p>机会成本始终是前瞻的：已沉没的支出用零进入本期目标，但占用仍可转售的厂房要用转售价进入。本课只切这一刀，不引入融资约束或不可逆投资的实物期权——那是宏观与公司金融的后课。</p>',15)),(e(),B(o,null,{default:E(()=>[i(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20ALL%5B%22%E4%B8%8A%E8%8A%82%E8%AF%BE%EF%BC%9A%E4%B8%80%E5%88%87%E6%8A%95%E5%85%A5%E5%8F%AF%E8%B0%83%22%5D%20--%3E%20SPLIT%5B%22%E6%9C%AC%E6%9C%9F%E5%8F%AF%E8%B0%83%20vs%20%E5%B7%B2%E5%9B%BA%E5%AE%9A%22%5D%0A%20%20SPLIT%20--%3E%20SUNK%5B%22%E6%B2%89%E6%B2%A1%EF%BC%9A%E4%BA%8B%E5%90%8E%E4%B8%8D%E5%8F%AF%E6%94%B6%E5%9B%9E%22%5D%0A%20%20SPLIT%20--%3E%20AVOID%5B%22%E5%8F%AF%E9%81%BF%E5%9B%BA%E5%AE%9A%EF%BC%9A%E6%9C%AA%E4%BB%98%E5%88%99%E5%8F%AF%E5%85%8D%22%5D%0A%20%20SUNK%20--%3E%20SR%5B%22%E7%9F%AD%E6%9C%9F%EF%BC%9Ap%20%E5%AF%B9%20AVC%22%5D%0A%20%20AVOID%20--%3E%20LR%5B%22%E9%95%BF%E6%9C%9F%EF%BC%9A%E8%BF%9B%E5%85%A5%E7%94%A8%E5%85%A8%E9%83%A8%20c_LR%22%5D%0A%20%20SR%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%B8%82%E5%9C%BA%E6%8A%8A%E7%9F%AD%E9%95%BF%E6%9C%9F%E4%BE%9B%E7%BB%99%E5%8A%A0%E6%80%BB%22%5D%0A%20%20LR%20--%3E%20LATER%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A("p",null,"本课仍是单一厂商、价格接受。市场有多少家、价格从哪来，下一课才拼。",-1)),a[4]||(a[4]=A("h2",{id:"机制",tabindex:"-1"},[t("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=A("p",null,"包络的机制：长期可以挑选 \\(z_f\\)，故任何产量上长期成本不会高于某一条已经选错规模的短期成本；在恰好选对的那一点，短、长期 MC 相等，否则还可以微调规模来省边际支出。Viner 当初在「短期 AC 是否切长期 AC」上画错过切点，后来的纠正正是包络：相切，不是相交穿过。",-1)),(e(),B(o,null,{default:E(()=>[i(r,{id:"mermaid-51",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E8%A7%82%E5%AF%9F%E5%BD%93%E5%89%8D%E4%BB%B7%E6%A0%BC%20p%22%5D%20--%3E%20Q1%7B%22p%20%E2%89%A5%20min%20AVC%EF%BC%9F%22%7D%0A%20%20Q1%20--%3E%7C%22%E5%90%A6%22%7C%20CLOSE%5B%22%E7%9F%AD%E6%9C%9F%E5%81%9C%E4%BA%A7%EF%BC%9A%E4%BA%A7%E9%87%8F%E5%BD%92%E9%9B%B6%22%5D%0A%20%20Q1%20--%3E%7C%22%E6%98%AF%22%7C%20Q2%7B%22p%20%E2%89%A5%20min%20AC%EF%BC%9F%22%7D%0A%20%20Q2%20--%3E%7C%22%E6%98%AF%22%7C%20PROF%5B%22%E4%BC%9A%E8%AE%A1%E5%88%A9%E6%B6%A6%E9%9D%9E%E8%B4%9F%EF%BC%8C%E7%BB%A7%E7%BB%AD%E5%B9%B6%E8%80%83%E8%99%91%E6%89%A9%E8%A7%84%E6%A8%A1%22%5D%0A%20%20Q2%20--%3E%7C%22%E5%90%A6%22%7C%20LOSS%5B%22%E4%BC%9A%E8%AE%A1%E4%BA%8F%E6%8D%9F%EF%BC%8C%E4%BD%86%E5%8F%AF%E5%8F%98%E6%88%90%E6%9C%AC%E5%B7%B2%E5%9B%9E%E6%9C%AC%22%5D%0A%20%20LOSS%20--%3E%20KEEP%5B%22%E4%BB%8D%E5%BA%94%E7%BB%A7%E7%BB%AD%EF%BC%9A%E6%AF%8F%E4%BB%B6%E6%94%B6%E5%85%A5%E9%83%BD%E5%9C%A8%E6%91%8A%E8%96%84%E6%B2%89%E6%B2%A1%E9%83%A8%E5%88%86%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p><span class="marginnote">直觉类比：长期 AC 是「每次都买合身衣服」的价格轨迹，短期 AC 是「将就穿去年那件」的轨迹。合身的总不会更贵；两条曲线只在身材恰好没变的那一点相切——这就是包络定理的成本曲线版本。</span></p><p>沉没影响进入的机制：进入决策比较的是进入后利润流与尚未付出的进入成本。一旦付出，历史成本退出一阶条件，只留下可变部分。这与<a href="/econ/risk-aversion">风险</a>课的「已实现损失不进期望」不是同一对象，但都禁止把沉没的数字再减一次。</p><p><span class="marginnote">不要把沉没成本写成限价簿上的已挂订单。订单能否撤、费用是否退，是微观结构规则；这里是生产计划的时间分层。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>连续时间、部分可逆、转售市场有折价，会把「沉没」变成连续的不可逆程度，本课不展开。学习效应、调整成本让 \\(z_f\\) 的选择带动态，长期不再是静态包络。IRS 的短期工厂一旦建好，竞争分析更脆，留给市场结构课。</p><p><span class="marginnote">常见误区：初学者容易把「亏了还继续生产」当成不理性。只要 \\(p\\ge\\mathrm{AVC}\\)，每件产品赚回的钱都超过其可变成本，能摊薄已沉没的支出；这时停产反而把「会计亏损」扩大成「亏掉全部固定成本」。</span></p><p>劳动力也不必天生可变、资本不必天生固定：哪一种冻住由调整速度决定。专用性资产把沉没接到敲竹杠，那是契约课。不要把沉没写成限价簿上已挂、能否撤销的订单。</p><p>后课默认：短期供给读可变成本与既定规模；长期成本是短期的下包络；沉没不进入本期一阶条件。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>短期有不可调投入；沉没是事后收不回，固定未必沉没。</li><li>停产看 AVC；进入与退出看长期成本。</li><li>长期 AC、MC 是短期族的包络，在最优规模处相切。</li><li>下一课把短、长期供给推进价格接受的市场。</li><li>出处：Viner, <em>Zeitschrift für Nationalökonomie</em>, 1931；Mas-Colell, Whinston and Green 第 5、10 章。</li></ul>',10))])}const u=s(p,[["render",m]]);export{D as __pageData,u as default};
